solution.garden:
function whenRunClicked() {
  game.changeCoins(50);
}

function whenSquareClicked(x, y) {
  if (game.coins() >= 10) {
    garden.build(x, y);
    game.changeCoins(-10);
  }
}

function everyTick() {
  if (game.every(30)) {
    garden.newBug();
  }
  if (garden.bugAtHouse()) {
    game.over();
  }
  if (garden.stopped() >= 10) {
    game.win();
  }
}

